pragma solidity >=0.8.0;
contract EventIdxDyn {
    event Pair(string indexed sIdx, string sVal, bytes indexed bIdx, bytes bVal);
    string public lastS;
    bytes public lastB;
    function emitPair(string memory s, bytes memory b) external {
        lastS = s;
        lastB = b;
        emit Pair(s, s, b, b);
    }
    function getLast() external view returns (string memory, bytes memory) {
        return (lastS, lastB);
    }
}
